import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";

const InvoiceIndex = () => {
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({
        buyerID: "",
        sellerID: "",
        product: "",
        minPrice: "",
        maxPrice: "",
        limit: "40"
    });
    const [buyerList, setBuyerList] = useState([]);
    const [sellerList, setSellerList] = useState([]);

    const deleteInvoice = async (id) => {
        try {
            await apiDelete("/api/invoices/" + id);
            setInvoices((prev) => prev.filter((item) => item.id !== id));
        } catch (error) {
            console.log(error.message);
            alert(error.message);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;

        setFilter((prev) => ({
            ...prev,
            [name]: value === "" ? null : value, // Pokud je prázdné, nastavíme na null
        }));
    };


    const handleFilterSubmit = (e) => {
        e.preventDefault();

        const filteredParams = Object.fromEntries(
            Object.entries(filter).filter(([_, value]) => value != null && value !== "")
        );

        console.log("🔎 Filtruji faktury s:", filteredParams); // Debugging

        const queryParams = new URLSearchParams(filteredParams).toString();
        apiGet(`/api/invoices?${queryParams}`).then((data) => setInvoices(data)).catch(err => {
            console.error("❌ Chyba při načítání faktur:", err);
        });
    };




    useEffect(() => {
        const fetchData = async () => {
            const invoicesData = await apiGet("/api/invoices");
            setInvoices(invoicesData);

            const personsData = await apiGet("/api/persons");
            setBuyerList(personsData);
            setSellerList(personsData);
        };

        fetchData();
    }, []);

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter
                filter={filter}
                handleChange={handleFilterChange}
                handleSubmit={handleFilterSubmit}
                confirm="Filtrovat"
                buyerList={buyerList}
                sellerList={sellerList}
            />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} label="Počet faktur:" />
        </div>
    );
};

export default InvoiceIndex;
